import request from '@/utils/request';

// Query {{entity}} list
export function list{{Entity}}(query?: Record<string, any>) {
  return request({
    url: '/{{module}}/{{entity}}/list',
    method: 'get',
    params: query,
  });
}

// Query {{entity}} detail
export function get{{Entity}}(id: number | string) {
  return request({
    url: '/{{module}}/{{entity}}/' + id,
    method: 'get',
  });
}

// Create {{entity}}
export function add{{Entity}}(data: Record<string, any>) {
  return request({
    url: '/{{module}}/{{entity}}',
    method: 'post',
    data,
  });
}

// Update {{entity}}
export function update{{Entity}}(data: Record<string, any>) {
  return request({
    url: '/{{module}}/{{entity}}',
    method: 'put',
    data,
  });
}

// Delete {{entity}}
export function del{{Entity}}(id: number | string) {
  return request({
    url: '/{{module}}/{{entity}}/' + id,
    method: 'delete',
  });
}
